from base_sensor import BaseVirtualSensor

class ADS1220_Simulator(BaseVirtualSensor):
    REG_WIDTH = 8  # This device uses 8-bit registers

    def __init__(self):
        super().__init__()
        # Initialize all registers to their reset values
        self.regs = {
            0x00: 0x00,  # CONFIG0
            0x01: 0x00,  # CONFIG1
            0x02: 0x00,  # CONFIG2
            0x03: 0x00,  # CONFIG3
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if nbytes == 2:
            return self.regs[addr]
        elif nbytes == 1:
            return (self.regs[addr] >> 8) & 0xFF
        else:
            raise ValueError("Invalid nbytes value for read_register")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if nbytes == 2:
            self.regs[addr] = data & 0xFF
        elif nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0xFF00) | (data << 8)
        else:
            raise ValueError("Invalid nbytes value for write_register")

